require_once __DIR__ . '/../../src/middleware/Auth.php';
require_once __DIR__ . '/../../src/models/Admin.php';
Auth::requireRole('admin', '/auth/login.php');
if (!PORTAL_EXTENSIONS_ENABLED) { http_response_code(503); exit('Admin tools are disabled.'); }
Admin::ensureAuditTable();
$user = Auth::user();
$stats = Admin::stats();
$pendingLecturers = PORTAL_EXTENSIONS_ENABLED ? Admin::pendingLecturers() : [];
