$role = $_GET['role'] ?? '';
$page = max(1, (int)($_GET['page'] ?? 1));
$userPage = Admin::users($search, $role, $page);
$payments = PORTAL_EXTENSIONS_ENABLED ? Admin::payments(['status' => $_GET['payment_status'] ?? '', 'course_id' => $_GET['course_id'] ?? '', 'student_id' => $_GET['student_id'] ?? '', 'date_from' => $_GET['date_from'] ?? '', 'date_to' => $_GET['date_to'] ?? '']) : [];
$courseOptions = Database::query('SELECT id, code, title FROM courses ORDER BY title')->fetchAll();
$educationCounts = EDUCATION_COURSE_TARGETING_ENABLED
	? Database::query("SELECT COALESCE(education_level, 'unknown') AS education_level, COUNT(*) AS total FROM users WHERE role = 'student' GROUP BY education_level")->fetchAll()
	: [];
$security = PORTAL_EXTENSIONS_ENABLED ? Admin::securitySummary() : ['pending_payments'=>0,'failed_callbacks'=>0,'suspended_users'=>0,'audit_events_24h'=>0,'unmatched_paid_enrollments'=>0];
$health = Admin::health();
$audit = PORTAL_EXTENSIONS_ENABLED ? Admin::recentAudit(50) : [];
$metrics = Admin::systemMetrics();
$siteSettings = [];
if (PORTAL_EXTENSIONS_ENABLED) {
	foreach (['maintenance_mode','new_registrations_enabled','student_course_applications_enabled','payments_enabled'] as $settingKey) {
		$siteSettings[$settingKey] = Admin::setting($settingKey, $settingKey === 'payments_enabled' ? '0' : '1');
	}
}
$courses = PORTAL_EXTENSIONS_ENABLED
 ? Database::query('SELECT c.id, c.code, c.title, c.status, c.price, u.name AS lecturer_name, (SELECT COUNT(*) FROM enrollments e WHERE e.course_id = c.id) AS enrollments, (SELECT COALESCE(SUM(p.amount_paid),0) FROM payments p WHERE p.course_id = c.id AND p.payment_status = \'success\') AS revenue FROM courses c JOIN users u ON u.id = c.lecturer_id ORDER BY c.created_at DESC LIMIT 200')->fetchAll()
 : Database::query('SELECT c.id, c.code, c.title, \'published\' AS status, NULL AS price, u.name AS lecturer_name, (SELECT COUNT(*) FROM enrollments e WHERE e.course_id = c.id) AS enrollments, 0 AS revenue FROM courses c JOIN users u ON u.id = c.lecturer_id ORDER BY c.created_at DESC LIMIT 200')->fetchAll();
$flash = $_SESSION['flash'] ?? null; unset($_SESSION['flash']);
$pageTitle = 'Admin Dashboard';
?>
<?php include __DIR__ . '/../../views/shared/header.php'; ?>
