bmission, or payment history?')" style="margin-top:.4rem"><input type="hidden" name="csrf_token" value="<?= Auth::csrfToken() ?>"><input type="hidden" name="user_id" value="<?= (int)$row['id'] ?>"><button class="btn btn-danger btn-sm" name="action" value="delete_user">Delete (no history only)</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><p class="form-hint">Page <?= $page ?> of <?= max(1,$userPage['pages']) ?> · <?= $userPage['total'] ?> users</p></div>
